select jsonb_build_object('functions',(select jsonb_agg(t order by t.schema,t.name,t.args) from (select n.nspname as schema,p.proname as name,pg_get_function_identity_arguments(p.oid) as args,md5(p.prosrc) as md5 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','app_private') and (p.proname like '%internal_user%' or p.proname in ('require_superadmin_internal_context','ensure_service_person_for_internal_actor','has_platform_permission')))t),'policies',(select jsonb_agg(t order by t.tablename,t.policyname) from (select schemaname,tablename,policyname,cmd,qual,with_check from pg_policies where schemaname='app_private' and tablename like 'superadmin_internal%')t)) as proof;
